"""Determines the current epsilon value.

    :param time_step: The current time step from the training procedure.
    :param fifty_percent_chance: The time step at which epsilon shall be 0.5.
    :param start_epsilon: The initial value for epsilon.
    :param min_epsilon: The minimal value for epsilon.
    :return: A probability for choosing a random action. (epsilon)
    """
def determine_current_epsilon(
    time_step: Any,
    fifty_percent_chance: Any = 100,
    start_epsilon: Any = 1.0,
    min_epsilon: Any = 0.1
) -> object {
    return max(min_epsilon, (start_epsilon / (1 + (time_step / fifty_percent_chance))));
}

""" Transform to convert SDK file/dir list output to something that
    more clearly distinguishes between files and directories. """
def transform_file_output(result: Any) -> object {
    import from collections { OrderedDict }
    new_result = [];
    iterable = result if isinstance(result, `list) else result.get('items', result);
    for item in iterable {
        new_entry = OrderedDict();
        entity_type = item['type'];
        is_dir = entity_type == 'dir';
        new_entry['Name'] = (item['name'] + '/') if is_dir else item['name'];
        new_entry['Content Length'] = ' '
            if is_dir
            else item['properties']['contentLength'];
        new_entry['Type'] = item['type'];
        new_entry['Last Modified'] = item['properties']['lastModified'] or ' ';
        new_result.append(new_entry);
    }
    return sorted(new_result, key=lambda (k: Any) { k['Name']; });
}

