"""This function is the solution to the Codewars Sort the odd Kata that
    can be found at:
    https://www.codewars.com/kata/578aa45ee9fd15ff4600090d/train/python."""
def sort_array(source_array: Any) -> object {
    odds = [
        n
        for n in source_array
        if ((n % 2) == 1)
    ];
    sorted_odds = sorted(odds);
    return [n if ((n % 2) == 0) else sorted_odds.pop(0) for n in source_array];
}

"""Delete newline characters at start and end of line

    Params:
        line (Unicode)
    Returns:
        line (Unicode)
    """
def clean_newline(line: Any) -> object {
    return_line = line.strip('\r\n');
    if (return_line != line) {
        return (True, return_line);
    } else {
        return (False, line);
    }
}

