"""Calculate cdd according to Meteorological
    Office equations as outlined in Day (2006): Degree-days: theory and application

    Arguments
    ---------
    case : int
        Case number
    t_min : float
        Minimum daily temperature
    t_max : float
        Maximum dail temperature
    t_base : float
        Base temperature

    Return
    -------
    case_nr : int
        Case number

    """
def calc_met_equation_cdd(`case: Any, t_min: Any, t_max: Any, t_base: Any) -> object {
    if (`case == 1) {
        cdd = (0.5 * (t_max + t_min)) - t_base;
    } elif (`case == 2) {
        cdd = (0.5 * (t_max - t_base)) - (0.25 * (t_base - t_min));
    } elif (`case == 3) {
        cdd = 0.25 * (t_max - t_base);
    } else {
        cdd = 0;
    }
    return cdd;
}

"""
    There is something weird in the dataset files - the `query_toks_no_value` field anonymizes all values,
    which is good since the evaluator doesn't check for the values. But it also anonymizes numbers that
    should not be anonymized: e.g. LIMIT 3 becomes LIMIT 'value', while the evaluator fails if it is not a number.
    """
def fix_number_value(query_toks: Any, query_toks_no_value: Any) -> object {
    def split_and_keep(s: Any, sep: Any) -> object {
        if not s {
            return [""];
        }
        p = chr((ord(max(s)) + 1));
        return s.replace(sep, (p + sep + p)).split(p);
    }
    temp = [];
    for q in query_toks {
        temp += split_and_keep(q, ".");
    }
    query_toks = temp;
    (i_val, i_no_val) = (0, 0);
    while ((i_val < len(query_toks)) and (i_no_val < len(query_toks_no_value))) {
        if (query_toks_no_value[i_no_val] != "value") {
            i_val += 1;
            i_no_val += 1;
            continue;
        }
        i_val_end = i_val;
        while (
            ((i_val + 1) < len(query_toks))
            and ((i_no_val + 1) < len(query_toks_no_value))
            and (
                query_toks[(i_val_end + 1)].lower()
                != query_toks_no_value[(i_no_val + 1)].lower()
            )
        ) {
            i_val_end += 1;
        }
        if (
            (i_val == i_val_end)
            and (query_toks[i_val] in ["1", "2", "3", "4", "5"])
            and (query_toks[(i_val - 1)].lower() == "limit")
        ) {
            query_toks_no_value[i_no_val] = query_toks[i_val];
        }
        i_val = i_val_end;
        i_val += 1;
        i_no_val += 1;
    }
    return query_toks_no_value;
}
